SET ROLE talus_fn;
CREATE TABLE app.ledger_account(tenant_id uuid NOT NULL,ledger_account_id uuid NOT NULL,account_code text NOT NULL,account_type text NOT NULL CHECK(account_type IN('asset','liability','equity','revenue','expense')),PRIMARY KEY(tenant_id,ledger_account_id),UNIQUE(tenant_id,account_code),FOREIGN KEY(tenant_id) REFERENCES app.tenant(tenant_id));
CREATE TABLE app.journal_entry(tenant_id uuid NOT NULL,journal_entry_id uuid NOT NULL,source_event text NOT NULL,processor_reference text,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),posted_by_principal_id uuid NOT NULL,PRIMARY KEY(tenant_id,journal_entry_id),UNIQUE(tenant_id,processor_reference),FOREIGN KEY(tenant_id,posted_by_principal_id) REFERENCES app.principal(tenant_id,principal_id));
CREATE TABLE app.ledger_posting(tenant_id uuid NOT NULL,journal_entry_id uuid NOT NULL,line_no integer NOT NULL,ledger_account_id uuid NOT NULL,direction text NOT NULL CHECK(direction IN('debit','credit')),amount_cents bigint NOT NULL CHECK(amount_cents>0),PRIMARY KEY(tenant_id,journal_entry_id,line_no),FOREIGN KEY(tenant_id,journal_entry_id) REFERENCES app.journal_entry(tenant_id,journal_entry_id),FOREIGN KEY(tenant_id,ledger_account_id) REFERENCES app.ledger_account(tenant_id,ledger_account_id));
CREATE OR REPLACE FUNCTION app.m05_balance() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM app.journal_entry e WHERE e.tenant_id=NEW.tenant_id AND e.journal_entry_id=NEW.journal_entry_id) AND (SELECT COALESCE(sum(CASE WHEN direction='debit' THEN amount_cents ELSE -amount_cents END),0) FROM app.ledger_posting WHERE tenant_id=NEW.tenant_id AND journal_entry_id=NEW.journal_entry_id)<>0 THEN RAISE EXCEPTION 'UNBALANCED_JOURNAL_ENTRY' USING ERRCODE='P0001';END IF;RETURN NULL;END;$$;
CREATE CONSTRAINT TRIGGER m05_balance_check AFTER INSERT OR UPDATE OR DELETE ON app.ledger_posting DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION app.m05_balance();
CREATE TRIGGER m05_account_append BEFORE UPDATE OR DELETE ON app.ledger_account FOR EACH ROW EXECUTE FUNCTION app.enforce_append_only();
CREATE TRIGGER m05_entry_append BEFORE UPDATE OR DELETE ON app.journal_entry FOR EACH ROW EXECUTE FUNCTION app.enforce_append_only();
CREATE TRIGGER m05_posting_append BEFORE UPDATE OR DELETE ON app.ledger_posting FOR EACH ROW EXECUTE FUNCTION app.enforce_append_only();
CREATE OR REPLACE FUNCTION app.post_journal_entry(p_id uuid,p_source text,p_ref text,p_debit uuid,p_credit uuid,p_amount bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();BEGIN PERFORM app.require_staff_role('staff');IF EXISTS(SELECT 1 FROM app.journal_entry WHERE tenant_id=t AND processor_reference=p_ref) THEN RETURN(SELECT journal_entry_id FROM app.journal_entry WHERE tenant_id=t AND processor_reference=p_ref);END IF;INSERT INTO app.journal_entry VALUES(t,p_id,p_source,p_ref,clock_timestamp(),app.current_context_principal_id());INSERT INTO app.ledger_posting VALUES(t,p_id,1,p_debit,'debit',p_amount),(t,p_id,2,p_credit,'credit',p_amount);PERFORM app.append_audit('ledger.entry_posted','journal_entry',p_id);RETURN p_id;END;$$;
CREATE OR REPLACE FUNCTION app.record_payment_capture(p_id uuid,p_ref text,p_debit uuid,p_credit uuid,p_amount bigint) RETURNS uuid LANGUAGE sql SECURITY DEFINER AS $$ SELECT app.post_journal_entry(p_id,'payment_capture',p_ref,p_debit,p_credit,p_amount) $$;
CREATE OR REPLACE FUNCTION app.record_refund(p_id uuid,p_ref text,p_debit uuid,p_credit uuid,p_amount bigint) RETURNS uuid LANGUAGE sql SECURITY DEFINER AS $$ SELECT app.post_journal_entry(p_id,'refund',p_ref,p_debit,p_credit,p_amount) $$;
CREATE OR REPLACE FUNCTION app.record_deposit_hold(p_id uuid,p_ref text,p_debit uuid,p_credit uuid,p_amount bigint) RETURNS uuid LANGUAGE sql SECURITY DEFINER AS $$ SELECT app.post_journal_entry(p_id,'deposit_hold',p_ref,p_debit,p_credit,p_amount) $$;
CREATE OR REPLACE FUNCTION app.record_deposit_release(p_id uuid,p_ref text,p_debit uuid,p_credit uuid,p_amount bigint) RETURNS uuid LANGUAGE sql SECURITY DEFINER AS $$ SELECT app.post_journal_entry(p_id,'deposit_release',p_ref,p_debit,p_credit,p_amount) $$;
DO $$ DECLARE x text;BEGIN FOREACH x IN ARRAY ARRAY['ledger_account','journal_entry','ledger_posting'] LOOP EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY;ALTER TABLE app.%I FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_context_policy ON app.%I USING(tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK(tenant_id=app.current_context_tenant_id() AND app.context_is_valid())',x,x,x);END LOOP;END;$$;
GRANT SELECT,INSERT,UPDATE,DELETE ON app.ledger_account,app.journal_entry,app.ledger_posting TO talus_fn;
REVOKE ALL ON app.ledger_account,app.journal_entry,app.ledger_posting FROM PUBLIC,talus_staff,talus_api,talus_customer;
RESET ROLE;
